// Leer modelo del nodo trigger, no del HTTP Request
const modelo = ($('When Executed by Another Workflow').first().json.modelo || '')
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .trim()
  .replace(/\s+/g, ' ');

console.log("modelo procesado:", modelo);

function getVehicleCode(m) {
  if (m.includes('hilux')) return '1';
  if (m.includes('corolla cross')) return '245';
  if (m.includes('corolla') && !m.includes('cross')) return '2';
  if (m.includes('yaris')) return '227';
  if (m.includes('etios')) return '225';
  if (m.includes('sw4')) return '226';
  if (m.includes('hiace')) return '224';
  if (m.includes('rav4') || m.includes('rav 4')) return '3';
  return null;
}

const codigoVehiculo = getVehicleCode(modelo);

return [{ json: { codigoVehiculo } }];
